const data = [40, 80, 150, 100, 60, 200, 120];
const svg = d3.select(document.body).append('svg').attr('width', 400).attr('height', 300);
const x = d3.scaleBand().domain(data.map((d, i) => i)).range([0, 400]).padding(0.1);
const y = d3.scaleLinear().domain([0, d3.max(data)]).range([300, 0]);
svg.selectAll('rect').data(data).enter().append('rect').attr('x', (d, i) => x(i)).attr('y', d => y(d)).attr('width', x.bandwidth()).attr('height', d => 300 - y(d)).attr('fill', '#4f8cf8');
